import { TreeItem } from "@vscode-elements/elements/dist/vscode-tree/vscode-tree"
import { getGitStatusColor, GitChange, getFileCodicon } from "../../../utils/reviewPanelHelpers"

interface TreeNode {
	name: string
	path: string
	type: 'file' | 'directory'
	children?: TreeNode[]
	file?: GitChange
}

function buildFileTree(changes: GitChange[]): TreeNode[] {
	const root: TreeNode[] = []
	
	changes.forEach(change => {
		const path = change.displayPath || change.path
		const normalizedPath = path.replace(/\\/g, '/')
		const parts = normalizedPath.split('/')
		
		let currentLevel = root
		let currentPath = ''
		
		for (let i = 0; i < parts.length - 1; i++) {
			const part = parts[i]
			currentPath = currentPath ? `${currentPath}/${part}` : part
			
			let dirNode = currentLevel.find(n => n.name === part && n.type === 'directory')
			
			if (!dirNode) {
				dirNode = {
					name: part,
					path: currentPath,
					type: 'directory',
					children: []
				}
				currentLevel.push(dirNode)
			}
			
			if (!dirNode.children) {
				dirNode.children = []
			}
			currentLevel = dirNode.children
		}
		
		const fileName = parts[parts.length - 1]
		const fileNode: TreeNode = {
			name: fileName,
			path: path,
			type: 'file',
			file: change
		}
		currentLevel.push(fileNode)
	})
	
	const compactFolders = (nodes: TreeNode[]): TreeNode[] => {
		return nodes.map(node => {
			if (node.type === 'directory' && node.children && node.children.length > 0) {
				while (node.children && node.children.length === 1 && node.children[0].type === 'directory') {
					const child: TreeNode = node.children[0]
					node.name = `${node.name}/${child.name}`
					node.path = child.path
					node.children = child.children
				}
				
				if (node.children) {
					node.children = compactFolders(node.children)
				}
			}
			
			return node
		})
	}
	
	const sortNodes = (nodes: TreeNode[]): TreeNode[] => {
		return nodes.sort((a, b) => {
			if (a.type !== b.type) {
				return a.type === 'directory' ? -1 : 1
			}
			return a.name.localeCompare(b.name)
		}).map(node => {
			if (node.children && node.children.length > 0) {
				node.children = sortNodes(node.children)
			}
			return node
		})
	}
	
	const sorted = sortNodes(root)
	return compactFolders(sorted)
}

function convertToTreeItems(nodes: TreeNode[]): TreeItem[] {
	return nodes.map(node => {
		if (node.type === 'directory') {
			return {
				label: node.name,
				value: `dir-${node.path}`,
				icons: {
					branch: "folder",
					leaf: "folder",
					open: "folder-opened"
				},
				subItems: node.children ? convertToTreeItems(node.children) : [],
				open: true
			}
		} else {
			const decorations = []
			
			if (node.file?.status) {
				decorations.push({
					appearance: "text" as const,
					content: node.file.status,
					color: getGitStatusColor(node.file.status),
					visibleWhen: "always" as const
				})
			}
			
			const displayName = node.file?.status === "R" && node.file?.old 
				? `${node.file.old} → ${node.name}`
				: node.name
			
			return {
				label: displayName,
				value: `file-${node.path}-${node.file?.status || ''}`,
				icons: {
					branch: getFileCodicon(node.path),
					leaf: getFileCodicon(node.path),
					open: getFileCodicon(node.path)
				},
				decorations
			}
		}
	})
}

export function buildVscodeTreeData(changes: GitChange[]): TreeItem[] {
	const tree = buildFileTree(changes)
	return convertToTreeItems(tree)
}