/**
 * Branch prefix constants used to identify branch types in the UI and backend.
 * These prefixes are prepended to branch names to indicate their type.
 */
export const BRANCH_PREFIXES = {
	CURRENT: "current:",
	DEFAULT: "default:",
	REMOTE: "remote:",
	LOCAL: "local:",
} as const

/**
 * Branch value constants (without prefixes)
 */
export const BRANCH_VALUES = {
	CURRENT: "current",
} as const

/**
 * Type guard to check if a branch string starts with a specific prefix
 */
export function hasBranchPrefix(branch: string, prefix: string): boolean {
	return branch.startsWith(prefix)
}

/**
 * Remove a branch prefix from a branch string
 */
export function removeBranchPrefix(branch: string, prefix: string): string {
	return branch.replace(prefix, "")
}

/**
 * Check which prefix a branch has, if any
 */
export function getBranchPrefix(branch: string): string | null {
	for (const prefix of Object.values(BRANCH_PREFIXES)) {
		if (hasBranchPrefix(branch, prefix)) {
			return prefix
		}
	}
	return null
}