import React, { forwardRef, memo, useState } from "react"
import { useTranslation } from "react-i18next"
import { SearchableSelect, SearchableSelectOption } from "../../../components/ui/searchable-select"
import { Input } from "../../../components/ui/input"
import type { GitHubIssue } from "../../../../../src/shared/IBM/review/ReviewWebviewMessage"

interface GithubIssueSelectorProps {
	githubIssues: GitHubIssue[]
	selectedIssue: string
	onIssueChange: (issueUrl: string) => void
	onKeyDown?: (e: React.KeyboardEvent) => void
	onOpenChange?: (open: boolean) => void
}

export const GithubIssueSelector = memo(forwardRef<HTMLButtonElement, GithubIssueSelectorProps>(({ githubIssues, selectedIssue, onIssueChange, onKeyDown, onOpenChange }, ref) => {
	const { t } = useTranslation("ibm")
	const [showUrlInput, setShowUrlInput] = useState<boolean>(false)
	const [customUrl, setCustomUrl] = useState<string>("")

	const handleOpenChange = (open: boolean) => {
		onOpenChange?.(open)
	}
	
	const githubissueOptions: SearchableSelectOption[] = [
		...githubIssues.map((githubissue) => {
			const isAssigned = githubissue.assignee
			const isCreator = githubissue.creator
			
			let suffix = ""
			if (isAssigned) {
				suffix = ` ${t("reviewPanel.assignedToYou")}`
			} else if (isCreator) {
				suffix = ` ${t("reviewPanel.createdByYou")}`
			}
			
			return {
				value: githubissue.url,
				label: `#${githubissue.number}: ${githubissue.title}${suffix}`
			}
		}),
		{
			value: "other",
			label: t("reviewPanel.otherIssue")
		}
	]

	const handleIssueChange = (value: string) => {
		if (value === "other") {
			setShowUrlInput(true)
			// Keep "other" selected in the dropdown
			onIssueChange("other")
		} else {
			setShowUrlInput(false)
			onIssueChange(value)
		}
	}

	const handleUrlChange = (e: React.ChangeEvent<HTMLInputElement>) => {
		const url = e.target.value
		setCustomUrl(url)
		
		// Match URLs with or without https:// prefix, supporting github.com and github.{org}.com
		const trimmedUrl = url.trim()
		if (trimmedUrl && trimmedUrl.match(/(?:https?:\/\/)?github(?:\.[^/]+)?\.com\/[^/]+\/[^/]+\/issues\/\d+/)) {
			// Normalize URL by adding https:// if missing
			const normalizedUrl = trimmedUrl.startsWith('http://') || trimmedUrl.startsWith('https://')
				? trimmedUrl
				: `https://${trimmedUrl}`
			onIssueChange(normalizedUrl)
		} else if (trimmedUrl) {
			// If there's text but it's not valid, keep "other" selected
			onIssueChange("other")
		} else {
			// If empty, keep "other" selected
			onIssueChange("other")
		}
	}

	const handleUrlKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
		if (e.key === "Escape") {
			e.preventDefault()
			setShowUrlInput(false)
			setCustomUrl("")
			onIssueChange("")
		}
	}

	return (
		<div className="px-4 pt-2 pb-0">
			<label className="block mb-1 text-sm uppercase tracking-wide font-semibold">
				{t("reviewPanel.selectIssue")}
			</label>
			<div onKeyDown={onKeyDown}>
				<SearchableSelect
					ref={ref}
					value={selectedIssue}
					onValueChange={handleIssueChange}
					onOpenChange={handleOpenChange}
					onKeyDown={onKeyDown}
					options={githubissueOptions}
					placeholder={t("reviewPanel.selectIssue")}
					searchPlaceholder={t("reviewPanel.searchIssue")}
					emptyMessage={t("reviewPanel.noIssuesFound")}
					className="w-full border-0 bg-vscode-input-background text-vscode-input-foreground px-2 py-1 border border-vscode-input-border rounded"
					data-testid="issue-select"
				/>
			</div>
			
			{showUrlInput && (
				<div className="mt-2">
					<label className="block mb-1 text-xs text-vscode-descriptionForeground">
						{t("reviewPanel.enterIssueUrl")}
					</label>
					<Input
						type="text"
						value={customUrl}
						onChange={handleUrlChange}
						onKeyDown={handleUrlKeyDown}
						placeholder={t("reviewPanel.issueUrlPlaceholder")}
						className="text-sm"
						autoFocus
					/>
				</div>
			)}
		</div>
	)
}))

GithubIssueSelector.displayName = "GithubIssueSelector"