import React, { memo, useRef, useImperativeHandle, forwardRef } from "react"
import { useTranslation } from "react-i18next"
import { Button } from "@/components/ui/button"

interface ReviewModeSelectorProps {
	mode: "branch" | "issue"
	onModeChange: (mode: "branch" | "issue") => void
	onKeyDown?: (e: React.KeyboardEvent) => void
}

export interface ReviewModeSelectorRef {
	focusBranchButton: () => void
	focusIssueButton: () => void
}

export const ReviewModeSelector = memo(forwardRef<ReviewModeSelectorRef, ReviewModeSelectorProps>(
	({ mode, onModeChange, onKeyDown }, ref) => {
		const { t } = useTranslation("ibm")
		const branchButtonRef = useRef<HTMLButtonElement>(null)
		const issueButtonRef = useRef<HTMLButtonElement>(null)

		useImperativeHandle(ref, () => ({
			focusBranchButton: () => branchButtonRef.current?.focus(),
			focusIssueButton: () => issueButtonRef.current?.focus(),
		}))

		const handleKeyDown = (e: React.KeyboardEvent<HTMLButtonElement>, buttonType: "branch" | "issue") => {
			if (e.key === "ArrowLeft" || e.key === "ArrowRight") {
				e.preventDefault()
				e.stopPropagation()
				const targetRef = buttonType === "branch" ? issueButtonRef : branchButtonRef
				targetRef.current?.focus()
			} else if (e.key === "ArrowDown") {
				e.preventDefault()
				e.stopPropagation()
				onKeyDown?.(e)
			}
		}

		return (
			<div className="px-4 pt-3 pb-2">
				<label className="block mb-2 text-sm uppercase tracking-wide font-semibold">
					{t("reviewPanel.reviewMode")}
				</label>
				<div className="flex gap-2">
					<Button
						ref={branchButtonRef}
						onClick={() => onModeChange("branch")}
						onKeyDown={(e) => handleKeyDown(e, "branch")}
						variant={mode === "branch" ? "primary" : "secondary"}
						className="flex-1 w-full rounded-sm focus:outline-none focus-visible:ring-1 focus-visible:ring-vscode-focusBorder"
						data-testid="branch-mode-button"
					>
						{t("reviewPanel.branchMode")}
					</Button>
					<Button
						ref={issueButtonRef}
						onClick={() => onModeChange("issue")}
						onKeyDown={(e) => handleKeyDown(e, "issue")}
						variant={mode === "issue" ? "primary" : "secondary"}
						className="flex-1 w-full rounded-sm focus:outline-none focus-visible:ring-1 focus-visible:ring-vscode-focusBorder"
						data-testid="issue-mode-button"
					>
						{t("reviewPanel.issueMode")}
					</Button>
				</div>
			</div>
		)
	}
))

ReviewModeSelector.displayName = "ReviewModeSelector"