import React, { memo, forwardRef } from "react"
import { useTranslation } from "react-i18next"

interface UncommittedCheckboxProps {
	checked: boolean
	onChange: (e: React.ChangeEvent<HTMLInputElement>) => void
	onKeyDown?: (e: React.KeyboardEvent) => void
}

export const UncommittedCheckbox = memo(forwardRef<HTMLInputElement, UncommittedCheckboxProps>(({ checked, onChange, onKeyDown }, ref) => {
	const { t } = useTranslation("ibm")

	return (
		<div className="px-4 pt-2 pb-0">
			<label className="flex items-center gap-1.5 normal-case tracking-normal font-normal cursor-pointer mb-0">
				<input
					ref={ref}
					type="checkbox"
					checked={checked}
					onChange={onChange}
					onKeyDown={onKeyDown}
					className="cursor-pointer m-0 w-4 h-4 rounded focus:outline focus:outline-1 focus:outline-vscode-focusBorder focus:outline-offset-1"
				/>
				{t("reviewPanel.includeUncommitted")}
			</label>
		</div>
	)
}))

UncommittedCheckbox.displayName = "UncommittedCheckbox"