import React, { memo, forwardRef } from "react"
import { useTranslation } from "react-i18next"
import { Button } from "../../../components/ui"

interface ReviewButtonProps {
	onClick: () => void
	onKeyDown?: (e: React.KeyboardEvent) => void
	disabled: boolean
}

export const ReviewButton = memo(forwardRef<HTMLButtonElement, ReviewButtonProps>(({ onClick, onKeyDown, disabled }, ref) => {
	const { t } = useTranslation("ibm")

	return (
		<div className="px-4 pt-2 pb-0">
			<Button
				ref={ref}
				onClick={onClick}
				onKeyDown={onKeyDown}
				disabled={disabled}
				variant="primary"
				className="w-full rounded-sm focus:outline-none focus-visible:ring-1 focus-visible:ring-vscode-focusBorder"
			>
				<span className="codicon codicon-play" />
				{t("reviewPanel.startReview")}
			</Button>
		</div>
	)
}))

ReviewButton.displayName = "ReviewButton"