import React, { memo, forwardRef } from "react"
import { useTranslation } from "react-i18next"

interface FileListHeaderProps {
	fileCount: number
	onKeyDown?: (e: React.KeyboardEvent) => void
}


export const FileListHeader = memo(forwardRef<HTMLDivElement, FileListHeaderProps>(({ fileCount, onKeyDown }, ref) => {
	const { t } = useTranslation("ibm")

	return (
		<div
			ref={ref}
			tabIndex={0}
			onKeyDown={onKeyDown}
			className="font-semibold text-vscode-foreground m-0 select-none flex items-center gap-1 py-1.5 px-4 text-sm uppercase tracking-wide"
		>
			<div className="flex items-center gap-1 flex-1">
				{t("reviewPanel.filesToBeReviewed")}
				<span className="text-vscode-descriptionForeground">({fileCount})</span>
			</div>
		</div>
	)
}))

FileListHeader.displayName = "FileListHeader"