import React, { useState, useEffect, useCallback, useMemo, useRef } from "react"
import { BranchSelector } from "./BranchSelector"
import { ReviewButton } from "./ReviewButton"
import { UncommittedCheckbox } from "./UncommittedCheckbox"
import { FileListHeader } from "./FileListHeader"
import { ReviewLegend } from "./ReviewLegend"
import { buildVscodeTreeData } from "./utils/buildVscodeTree"
import { GitChange } from "../../utils/reviewPanelHelpers"
import "@vscode-elements/elements"
import "@vscode-elements/elements/dist/vscode-tree"
import type { VscTreeSelectEvent } from "@vscode-elements/elements/dist/vscode-tree/vscode-tree"
import type { VscodeTree } from "@vscode-elements/elements/dist/vscode-tree/vscode-tree"
import { ReviewModeSelector, type ReviewModeSelectorRef } from "./ReviewModeSelector"
import { GithubIssueSelector } from "./GithubIssueSelector"
import type { GitHubIssue } from "../../../../../src/shared/IBM/review/ReviewWebviewMessage"
import { BRANCH_PREFIXES, BRANCH_VALUES, hasBranchPrefix, removeBranchPrefix } from "../../../../../packages/types/src/ibm/branch-prefixes"

export const BobReviewApp: React.FC<{ vscode: any }> = ({ vscode }) => {
    const [mode, setMode] = useState<"branch" | "issue">("branch")
    const [branches, setBranches] = useState<string[]>([])
    const [githubIssues, setGithubIssues] = useState<GitHubIssue[]>([])
    const [changes, setChanges] = useState<GitChange[]>([])
    const [selectedBranch, setSelectedBranch] = useState<string>(BRANCH_VALUES.CURRENT)
    const [selectedIssue, setSelectedIssue] = useState("")
    const [includeUncommitted, setIncludeUncommitted] = useState(true)
    const [isBranchSelectorOpen, setIsBranchSelectorOpen] = useState(false)
    const [isGithubIssueSelectorOpen, setIsGithubIssueSelectorOpen] = useState(false)
    const [isTreeMounted, setIsTreeMounted] = useState(false)
    const treeRef = useRef<VscodeTree | null>(null)

    const isReviewingCurrentLocal = selectedBranch === BRANCH_VALUES.CURRENT

    const treeData = useMemo(() => {
        const filtered = changes.filter(row => !row.excluded)
        return buildVscodeTreeData(filtered)
    }, [changes])
    
    const setTreeRef = useCallback((node: VscodeTree | null) => {
        treeRef.current = node
        setIsTreeMounted(!!node)
    }, [])

    const handleTreeSelect = useCallback((event: VscTreeSelectEvent) => {
        const { value } = event.detail
        
        if (typeof value === 'string' && value.startsWith('file-')) {
            const match = value.match(/^file-(.+)-([AMDRUC])$/) // ibm_change: Added C for FileStatus.COPIED
            if (match) {
                const [, path, status] = match
                vscode.postMessage({ type: "openFile", path, status })
            }
        }
    }, [vscode])

    const modeSelectorRef = useRef<ReviewModeSelectorRef>(null)
    const branchSelectRef = useRef<HTMLButtonElement>(null)
    const githubIssueSelectorRef = useRef<HTMLButtonElement>(null)
    const startButtonRef = useRef<HTMLButtonElement>(null)
    const checkboxRef = useRef<HTMLInputElement>(null)
    const filesHeaderRef = useRef<HTMLDivElement>(null)

    const focusElement = (ref: React.RefObject<HTMLElement>) => {
        ref.current?.focus()
    }

    const handleModeSelectorKeyDown = useCallback((e: React.KeyboardEvent) => {
        if (e.key === 'ArrowDown') {
            e.preventDefault()
            focusElement(mode === "branch" ? branchSelectRef : startButtonRef)
        }
    }, [mode])

    const handleBranchSelectKeyDown = useCallback((e: React.KeyboardEvent) => {
        if (!isBranchSelectorOpen) {
            if (e.key === 'ArrowDown') {
                e.preventDefault()
                e.stopPropagation()
                focusElement(startButtonRef)
            } else if (e.key === 'ArrowUp') {
                e.preventDefault()
                e.stopPropagation()
                if (mode === "branch") {
                    modeSelectorRef.current?.focusBranchButton()
                } else {
                    modeSelectorRef.current?.focusIssueButton()
                }
            }
        }
    }, [isBranchSelectorOpen, mode])

    const handleStartButtonKeyDown = useCallback((e: React.KeyboardEvent) => {
        if (e.key === 'ArrowDown') {
            e.preventDefault()
            if (mode === "branch") {
                focusElement(checkboxRef)
            }
        } else if (e.key === 'ArrowUp') {
            e.preventDefault()
            if (mode === "branch") {
                focusElement(branchSelectRef)
            }
        }
    }, [mode])

    const handleCheckboxKeyDown = useCallback(
		(e: React.KeyboardEvent) => {
			if (e.key === "Enter" || e.key === " ") {
				e.preventDefault()
				const newValue = !includeUncommitted
				setIncludeUncommitted(newValue)
				vscode.postMessage({ type: "requestFileChanges", branch: selectedBranch, includeUncommitted: newValue })
			} else if (e.key === "ArrowDown") {
				e.preventDefault()
				focusElement(filesHeaderRef)
			} else if (e.key === "ArrowUp") {
				e.preventDefault()
				focusElement(startButtonRef)
			}
		},
		[includeUncommitted, selectedBranch, vscode],
	)

    const handleToggleKeyDown = useCallback((e: React.KeyboardEvent) => {
        if (e.key === 'ArrowDown') {
            e.preventDefault()
            treeRef.current?.focus()
        } else if (e.key === 'ArrowUp') {
            e.preventDefault()
            focusElement(checkboxRef)
        }
    }, [])

    const handleMessage = useCallback((event: MessageEvent) => {
        const message = event.data
        if (message.type === "branches") {
            const receivedBranches = message.branches || []
            setBranches(receivedBranches)
            
            const defaultBranch = receivedBranches.find((br: string) => hasBranchPrefix(br, BRANCH_PREFIXES.DEFAULT))
            const branchToUse = defaultBranch ? removeBranchPrefix(defaultBranch, BRANCH_PREFIXES.DEFAULT) : BRANCH_VALUES.CURRENT
            
            if (defaultBranch) {
                setSelectedBranch(branchToUse)
            }
            
            vscode.postMessage({ type: "requestFileChanges", branch: branchToUse, includeUncommitted: true })
        }
        if (message.type === "fileChanges") {
            setChanges(message.changes || [])
        }
        if (message.type === "branchChanged") {
            setSelectedBranch(message.branch || BRANCH_VALUES.CURRENT)
        }
        if (message.type === "githubIssues") {
            setGithubIssues(message.githubIssues || [])
        }
    }, [vscode])

    useEffect(() => {
        window.addEventListener("message", handleMessage)
        return () => {
            window.removeEventListener("message", handleMessage)
        }
    }, [handleMessage])

    useEffect(() => {
        vscode.postMessage({ type: "ready" })
    }, [vscode])

    const handleBranchChange = (branch: string) => {
        setSelectedBranch(branch)
        vscode.postMessage({ type: "requestFileChanges", branch, includeUncommitted: includeUncommitted})
    }

    const handleStartReview = () => {
        if (mode === "issue") {
            vscode.postMessage({
                type: "startReview",
                mode: "issue",
                issueUrl: selectedIssue,
            })
        } else {
            vscode.postMessage({
                type: "startReview",
                mode: "branch",
                branch: selectedBranch,
                includeUncommitted: isReviewingCurrentLocal ? true : includeUncommitted,
            })
        }
    }

    const handleModeChange = useCallback((newMode: "branch" | "issue") => {
        setMode(newMode)
        if (newMode === "branch") {
            vscode.postMessage({ type: "requestFileChanges", branch: selectedBranch, includeUncommitted: includeUncommitted })
        }
    }, [selectedBranch, includeUncommitted, vscode])

    const handleIssueChange = (issueUrl: string) => {
        setSelectedIssue(issueUrl)
    }

    const handleUncommittedCheck = (e: React.ChangeEvent<HTMLInputElement>) => {
        const newValue = e.target.checked
        setIncludeUncommitted(newValue)
        vscode.postMessage({ type: "requestFileChanges", branch: selectedBranch, includeUncommitted: newValue})
    }

    useEffect(() => {
        const treeElement = treeRef.current
        if (!treeElement) return

        const selectHandler = (event: CustomEvent) => {
            handleTreeSelect(event as VscTreeSelectEvent)
        }

        treeElement.addEventListener("vsc-tree-select", selectHandler)

        return () => {
            treeElement.removeEventListener("vsc-tree-select", selectHandler)
        }
    }, [handleTreeSelect])

    useEffect(() => {
        if (treeRef.current && mode === "branch" && isTreeMounted) {
            // Always update tree data, even when empty, to ensure UI clears properly
            treeRef.current.data = treeData
        }
    }, [treeData, mode, isTreeMounted])


    const handleIssueSelectKeyDown = useCallback((e: React.KeyboardEvent) => {
        if (!isGithubIssueSelectorOpen) {
            if (e.key === 'ArrowDown') {
                e.preventDefault()
                e.stopPropagation()
                focusElement(startButtonRef)
            } else if (e.key === 'ArrowUp') {
                e.preventDefault()
                e.stopPropagation()
                if (mode === "issue") {
                    modeSelectorRef.current?.focusIssueButton()
                } else {
                    modeSelectorRef.current?.focusBranchButton()
                }
            }
        }
    }, [isGithubIssueSelectorOpen, mode])

    return (
        <div className="font-display text-vscode-foreground bg-vscode-sideBar-background text-base flex flex-col h-screen min-h-screen overflow-hidden w-full">
            <ReviewModeSelector 
                ref={modeSelectorRef}
                mode={mode} 
                onModeChange={handleModeChange}
                onKeyDown={handleModeSelectorKeyDown}
            />

            {mode === "branch" ? (
                <>
                    <BranchSelector
                        ref={branchSelectRef}
                        branches={branches}
                        selectedBranch={selectedBranch}
                        onBranchChange={handleBranchChange}
                        onKeyDown={handleBranchSelectKeyDown}
                        onOpenChange={setIsBranchSelectorOpen}
                    />
                    <ReviewButton
                        ref={startButtonRef}
                        onClick={handleStartReview}
                        onKeyDown={handleStartButtonKeyDown}
                        disabled={changes.length === 0}
                    />

                    {!isReviewingCurrentLocal && (
                        <UncommittedCheckbox
                            ref={checkboxRef}
                            checked={includeUncommitted}
                            onChange={handleUncommittedCheck}
                            onKeyDown={handleCheckboxKeyDown}
                        />
                    )}
                </>
            ) : (
                <>
                    <GithubIssueSelector
                        ref={githubIssueSelectorRef}
                        githubIssues={githubIssues}
                        selectedIssue={selectedIssue}
                        onIssueChange={handleIssueChange}
                        onKeyDown={handleIssueSelectKeyDown}
                        onOpenChange={setIsGithubIssueSelectorOpen}
                    />

                    <ReviewButton
                        ref={startButtonRef}
                        onClick={handleStartReview}
                        onKeyDown={handleStartButtonKeyDown}
                        disabled={!selectedIssue || selectedIssue === "other"}
                    />
                </>
            )}

            {mode === "branch" && (
                <>
                    <FileListHeader
                        ref={filesHeaderRef}
                        fileCount={changes.length}
                        onKeyDown={handleToggleKeyDown}
                    />

                    <div id="file-list" className="overflow-y-auto flex-1 min-h-0">
                        <vscode-tree key={`tree-${mode}-${includeUncommitted}`} ref={setTreeRef} indent-guides={true} arrows={true} indent={16} />
                    </div>
                </>
            )}

            <ReviewLegend />
        </div>
    )
}