import React, { memo, forwardRef } from "react"
import { useTranslation } from "react-i18next"
import { SearchableSelect, SearchableSelectOption } from "../../../components/ui/searchable-select"
import { BRANCH_PREFIXES, BRANCH_VALUES, hasBranchPrefix, removeBranchPrefix } from "../../../../../packages/types/src/ibm/branch-prefixes"

interface BranchSelectorProps {
	branches: string[]
	selectedBranch: string
	onBranchChange: (branch: string) => void
	onKeyDown?: (e: React.KeyboardEvent) => void
	onOpenChange?: (open: boolean) => void
}

export const BranchSelector = memo(forwardRef<HTMLButtonElement, BranchSelectorProps>(({ branches, selectedBranch, onBranchChange, onKeyDown, onOpenChange }, ref) => {
	const { t } = useTranslation("ibm")
	
	const handleOpenChange = (open: boolean) => {
		onOpenChange?.(open)
	}

	const branchOptions: SearchableSelectOption[] = branches.map((br) => {
		const isCurrentBranch = hasBranchPrefix(br, BRANCH_PREFIXES.CURRENT)
		const isDefaultBranch = hasBranchPrefix(br, BRANCH_PREFIXES.DEFAULT)
		const isRemoteBranch = hasBranchPrefix(br, BRANCH_PREFIXES.REMOTE)
		const isLocalBranch = hasBranchPrefix(br, BRANCH_PREFIXES.LOCAL)
		
		if (isCurrentBranch) {
			return {
				value: BRANCH_VALUES.CURRENT,
				label: `${removeBranchPrefix(br, BRANCH_PREFIXES.CURRENT)} ${t("reviewPanel.currentBranch")}`
			}
		}
		
		if (isDefaultBranch) {
			const branchName = removeBranchPrefix(br, BRANCH_PREFIXES.DEFAULT)
			return {
				value: branchName,
				label: `${branchName} ${t("reviewPanel.defaultBranch")}`
			}
		}
		
		if (isRemoteBranch) {
			const branchName = removeBranchPrefix(br, BRANCH_PREFIXES.REMOTE)
			return {
				value: branchName,
				label: `${branchName} ${t("reviewPanel.remoteBranch")}`
			}
		}
		
		if (isLocalBranch) {
			const branchName = removeBranchPrefix(br, BRANCH_PREFIXES.LOCAL)
			return {
				value: branchName,
				label: `${branchName} ${t("reviewPanel.localBranch")}`
			}
		}
		
		return { value: br, label: br }
	})

	return (
		<div className="px-4 pt-2 pb-0">
			<label className="block mb-1 text-sm uppercase tracking-wide font-semibold">
				{t("reviewPanel.reviewAgainst")}
			</label>
			<SearchableSelect
				ref={ref}
				value={selectedBranch}
				onValueChange={onBranchChange}
				onOpenChange={handleOpenChange}
				onKeyDown={onKeyDown}
				options={branchOptions}
				placeholder={selectedBranch}
				searchPlaceholder={t("reviewPanel.searchBranch")}
				emptyMessage={t("reviewPanel.noBranchesFound")}
				className="w-full border-0 bg-vscode-input-background text-vscode-input-foreground px-2 py-1 border border-vscode-input-border rounded"
				data-testid="branch-select"
			/>
		</div>
	)
}))

BranchSelector.displayName = "BranchSelector"