export interface GitChange {
	status: string
	path: string
	old?: string
	displayPath?: string
	displayOld?: string
	excluded?: boolean
}

export enum FileStatus {
	ADDED = "A",
	MODIFIED = "M",
	DELETED = "D",
	RENAMED = "R",
	UNTRACKED = "U",
	COPIED = "C",
	IGNORED = "!"
}

export const getGitStatusColor = (status: string): string => {
	switch (status) {
		case FileStatus.MODIFIED:
			return "var(--vscode-gitDecoration-modifiedResourceForeground)"
		case FileStatus.ADDED:
			return "var(--vscode-gitDecoration-addedResourceForeground)"
		case FileStatus.DELETED:
			return "var(--vscode-gitDecoration-deletedResourceForeground)"
		case FileStatus.RENAMED:
			return "var(--vscode-gitDecoration-renamedResourceForeground)"
		case FileStatus.UNTRACKED:
			return "var(--vscode-gitDecoration-untrackedResourceForeground)"
		default:
			return "var(--vscode-foreground)"
	}
}

export const getFileCodicon = (path: string): string => {
	const lastDot = path.lastIndexOf(".")
	const ext = lastDot === -1 ? "" : path.substring(lastDot + 1).toLowerCase()

	switch (ext) {
		case "txt":
		case "log":
		case "csv":
		case "tsv":
		case "pdf":
		case "doc":
		case "docx":
		case "rtf":
			return "file"
		case "json":
			return "json"
		case "md":
			return "markdown"
		case "yml":
		case "yaml":
			return "symbol-key"
		case "css":
		case "scss":
		case "less":
			return "symbol-color"
		default:
			return "file-code"
	}
}

export const getGitStatusClassName = (status: string): string => {
	switch (status) {
		case FileStatus.MODIFIED:
			return "text-vscode-gitDecoration-modifiedResourceForeground"
		case FileStatus.ADDED:
			return "text-vscode-gitDecoration-addedResourceForeground"
		case FileStatus.DELETED:
			return "text-vscode-gitDecoration-deletedResourceForeground"
		case FileStatus.RENAMED:
			return "text-vscode-gitDecoration-renamedResourceForeground"
		case FileStatus.UNTRACKED:
			return "text-vscode-gitDecoration-untrackedResourceForeground"
		default:
			return "text-vscode-foreground"
	}
}